type Key = keyof typeof PATHS;
export type IconName = { [K in Key]: K extends `linear:${infer N}` ? N : never }[Key];

export function Icon({
  name,
  filled = false,
  className,
  style,
  label,
  strokeWidth,
}: {
  name: IconName;
  /** Variante pleine (actif). */
  filled?: boolean;
  className?: string;
  style?: CSSProperties;
  /** Nom accessible. Sans lui l'icône est décorative (`aria-hidden`). */
  label?: string;
  strokeWidth?: number;
}) {
  const markup = PATHS[`${filled ? "bold" : "linear"}:${name}` as Key];
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="none"
      strokeWidth={strokeWidth ?? 1.5}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn("size-[1.125rem] shrink-0", className)}
      style={style}
      dangerouslySetInnerHTML={{ __html: markup }}
    />
  );
}
